//! GitHub App keys and JWT authentication.
//!
//! An app's private key is a 2048-bit RSA key generated by forge and handed to the owner once as
//! a PKCS#1 PEM (`-----BEGIN RSA PRIVATE KEY-----`, like GitHub). Only the public key is stored.
//! Apps authenticate as themselves with a JWT signed RS256 by that key: `iss` = the app id (or
//! client id), `iat`, and `exp` at most 10 minutes after `iat` (60 s clock drift tolerated).
use aws_lc_rs::encoding::AsDer;
use aws_lc_rs::rsa::{KeyPair, KeySize};
use aws_lc_rs::signature::{self, KeyPair as _, UnparsedPublicKey};
use base64::Engine;
use serde_json::Value;
use sha2::{Digest, Sha256};

const B64URL: base64::engine::GeneralPurpose = base64::engine::general_purpose::URL_SAFE_NO_PAD;
const B64: base64::engine::GeneralPurpose = base64::engine::general_purpose::STANDARD;

/// Longest accepted JWT lifetime (`exp - iat`), like GitHub.
pub const MAX_LIFETIME_SECS: i64 = 600;
/// Clock drift tolerated on `iat`/`exp`.
pub const DRIFT_SECS: i64 = 60;

/// A freshly generated key: the private key PEM (shown once) and the stored public parts.
pub struct NewKey {
    pub pem: String,
    pub public_key: Vec<u8>,
    pub fingerprint: String,
}

fn der_len(buf: &[u8], pos: &mut usize) -> Option<usize> {
    let first = *buf.get(*pos)?;
    *pos += 1;
    if first < 0x80 {
        return Some(first as usize);
    }
    let n = (first & 0x7f) as usize;
    if n == 0 || n > 4 {
        return None;
    }
    let mut len = 0usize;
    for _ in 0..n {
        len = (len << 8) | *buf.get(*pos)? as usize;
        *pos += 1;
    }
    Some(len)
}

/// Reads one TLV at `pos`; returns (tag, content range) and advances past it.
fn der_tlv(buf: &[u8], pos: &mut usize) -> Option<(u8, std::ops::Range<usize>)> {
    let tag = *buf.get(*pos)?;
    *pos += 1;
    let len = der_len(buf, pos)?;
    let start = *pos;
    let end = start.checked_add(len)?;
    if end > buf.len() {
        return None;
    }
    *pos = end;
    Some((tag, start..end))
}

/// The RFC 8017 `RSAPrivateKey` inside an RFC 5208 PKCS#8 `PrivateKeyInfo`.
pub fn pkcs8_to_pkcs1(pkcs8: &[u8]) -> Option<Vec<u8>> {
    let mut pos = 0;
    let (tag, body) = der_tlv(pkcs8, &mut pos)?;
    if tag != 0x30 {
        return None;
    }
    let inner = &pkcs8[body];
    let mut p = 0;
    let (t1, _) = der_tlv(inner, &mut p)?; // version
    let (t2, _) = der_tlv(inner, &mut p)?; // algorithm identifier
    let (t3, key) = der_tlv(inner, &mut p)?; // privateKey OCTET STRING
    if t1 != 0x02 || t2 != 0x30 || t3 != 0x04 {
        return None;
    }
    Some(inner[key].to_vec())
}

pub fn pem(label: &str, der: &[u8]) -> String {
    let b = B64.encode(der);
    let mut out = format!("-----BEGIN {label}-----\n");
    for chunk in b.as_bytes().chunks(64) {
        out.push_str(std::str::from_utf8(chunk).unwrap_or_default());
        out.push('\n');
    }
    out.push_str(&format!("-----END {label}-----\n"));
    out
}

/// `SHA256:<base64>` of the key's SubjectPublicKeyInfo, as GitHub shows key fingerprints.
pub fn fingerprint(public_key: &[u8]) -> String {
    let spki = aws_lc_rs::rsa::PublicKey::from_der(public_key)
        .ok()
        .and_then(|k| k.as_der().ok().map(|d| d.as_ref().to_vec()))
        .unwrap_or_else(|| public_key.to_vec());
    format!("SHA256:{}", B64.encode(Sha256::digest(&spki)))
}

/// Generates a new RSA-2048 key pair.
pub fn generate_key() -> anyhow::Result<NewKey> {
    let kp = KeyPair::generate(KeySize::Rsa2048).map_err(|_| anyhow::anyhow!("RSA key generation failed"))?;
    let pkcs8 = kp.as_der().map_err(|_| anyhow::anyhow!("RSA key encoding failed"))?;
    let pkcs1 = pkcs8_to_pkcs1(pkcs8.as_ref()).ok_or_else(|| anyhow::anyhow!("unexpected PKCS#8 layout"))?;
    let public_key = kp.public_key().as_ref().to_vec();
    Ok(NewKey { pem: pem("RSA PRIVATE KEY", &pkcs1), fingerprint: fingerprint(&public_key), public_key })
}

/// Signs `claims` as an RS256 JWT with a PKCS#1 or PKCS#8 PEM private key (used by tests and
/// tools; the server itself never holds private keys).
pub fn sign_jwt(pem_text: &str, claims: &Value) -> anyhow::Result<String> {
    let body: String = pem_text.lines().filter(|l| !l.starts_with("-----")).collect();
    let der = B64.decode(body.trim())?;
    let kp = KeyPair::from_der(&der).or_else(|_| KeyPair::from_pkcs8(&der)).map_err(|e| anyhow::anyhow!("bad key: {e}"))?;
    let header = B64URL.encode(br#"{"alg":"RS256","typ":"JWT"}"#);
    let payload = B64URL.encode(serde_json::to_vec(claims)?);
    let input = format!("{header}.{payload}");
    let mut sig = vec![0u8; kp.public_modulus_len()];
    kp.sign(&signature::RSA_PKCS1_SHA256, &aws_lc_rs::rand::SystemRandom::new(), input.as_bytes(), &mut sig)
        .map_err(|_| anyhow::anyhow!("signing failed"))?;
    Ok(format!("{input}.{}", B64URL.encode(sig)))
}

/// Why a JWT was rejected (the message GitHub returns with 401).
#[derive(Debug, PartialEq, Eq)]
pub enum JwtError {
    Malformed,
    BadSignature,
    Expired,
    TooLong,
    IssuedInFuture,
    MissingIssuer,
}

impl JwtError {
    pub fn message(&self) -> &'static str {
        match self {
            JwtError::Malformed | JwtError::BadSignature => "A JSON web token could not be decoded",
            JwtError::Expired => "'Expiration time' claim ('exp') must be a numeric value representing the future time at which the assertion expires",
            JwtError::TooLong => "'Expiration time' claim ('exp') is too far in the future",
            JwtError::IssuedInFuture => "'Issued at' claim ('iat') must be an Integer representing the time that the assertion was issued",
            JwtError::MissingIssuer => "'Issuer' claim ('iss') must be an Integer",
        }
    }
}

/// A structurally valid JWT whose signature is not checked yet.
pub struct Unverified {
    pub issuer: String,
    signing_input: String,
    signature: Vec<u8>,
}

fn b64url(s: &str) -> Option<Vec<u8>> {
    B64URL.decode(s.trim_end_matches('=')).ok()
}

/// Parses `token` and checks its header and time claims against `now` (unix seconds).
pub fn parse(token: &str, now: i64) -> Result<Unverified, JwtError> {
    let mut parts = token.split('.');
    let (Some(h), Some(p), Some(s), None) = (parts.next(), parts.next(), parts.next(), parts.next()) else {
        return Err(JwtError::Malformed);
    };
    let header: Value = b64url(h).and_then(|b| serde_json::from_slice(&b).ok()).ok_or(JwtError::Malformed)?;
    if header.get("alg").and_then(Value::as_str) != Some("RS256") {
        return Err(JwtError::Malformed);
    }
    let claims: Value = b64url(p).and_then(|b| serde_json::from_slice(&b).ok()).ok_or(JwtError::Malformed)?;
    let signature = b64url(s).ok_or(JwtError::Malformed)?;
    let num = |k: &str| claims.get(k).and_then(|v| v.as_i64().or_else(|| v.as_f64().map(|f| f as i64)));
    let exp = num("exp").ok_or(JwtError::Expired)?;
    let iat = num("iat").ok_or(JwtError::IssuedInFuture)?;
    if exp <= now - DRIFT_SECS {
        return Err(JwtError::Expired);
    }
    if iat > now + DRIFT_SECS {
        return Err(JwtError::IssuedInFuture);
    }
    if exp - iat > MAX_LIFETIME_SECS + DRIFT_SECS || exp > now + MAX_LIFETIME_SECS + DRIFT_SECS {
        return Err(JwtError::TooLong);
    }
    let issuer = match claims.get("iss") {
        Some(Value::String(s)) if !s.is_empty() => s.clone(),
        Some(Value::Number(n)) => n.to_string(),
        _ => return Err(JwtError::MissingIssuer),
    };
    Ok(Unverified { issuer, signing_input: format!("{h}.{p}"), signature })
}

impl Unverified {
    /// Whether the signature verifies against one of `keys` (RSAPublicKey DER).
    pub fn verify<'a>(&self, keys: impl IntoIterator<Item = &'a [u8]>) -> bool {
        keys.into_iter().any(|k| {
            UnparsedPublicKey::new(&signature::RSA_PKCS1_2048_8192_SHA256, k)
                .verify(self.signing_input.as_bytes(), &self.signature)
                .is_ok()
        })
    }
}

/// Whether a bearer credential looks like a JWT (three base64url segments, header `eyJ`).
pub fn looks_like_jwt(s: &str) -> bool {
    s.starts_with("eyJ") && s.matches('.').count() == 2
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn keys_sign_and_verify() {
        let k = generate_key().unwrap();
        assert!(k.pem.starts_with("-----BEGIN RSA PRIVATE KEY-----\n"));
        assert!(k.fingerprint.starts_with("SHA256:"));
        let now = chrono::Utc::now().timestamp();
        let jwt = sign_jwt(&k.pem, &json!({"iss": 42, "iat": now - 30, "exp": now + 540})).unwrap();
        assert!(looks_like_jwt(&jwt));
        let u = parse(&jwt, now).unwrap();
        assert_eq!(u.issuer, "42");
        assert!(u.verify([k.public_key.as_slice()]));
        let other = generate_key().unwrap();
        assert!(!u.verify([other.public_key.as_slice()]));
        // lifetime and expiry checks
        let long = sign_jwt(&k.pem, &json!({"iss": "Iv1.x", "iat": now, "exp": now + 3600})).unwrap();
        assert_eq!(parse(&long, now).err(), Some(JwtError::TooLong));
        let old = sign_jwt(&k.pem, &json!({"iss": 1, "iat": now - 1200, "exp": now - 700})).unwrap();
        assert_eq!(parse(&old, now).err(), Some(JwtError::Expired));
        assert_eq!(parse("a.b", now).err(), Some(JwtError::Malformed));
    }
}
